local function number(ae,af,ag)
if ae==nil then
ae=ag
end
assert(type(ae)=="number"and ae==ae and math.abs(ae)<math.huge,
"GIFBackground."..af.." must be a finite number")
return ae
end

local function positiveInteger(ae,af)
ae=number(ae,af)
assert(ae>0 and ae%1==0,"GIFBackground."..af.." must be a positive integer")
return ae
end

function ad.Validate(ae)
assert(type(ae)=="table","GIFBackground must be a table")
assert(ae.Type==nil or ae.Type=="SpriteSheet","GIFBackground.Type must be SpriteSheet")
assert(type(ae.Asset)=="string"and(ae.Asset:match"^rbxassetid://%d+$"or ae.Asset:match"^rbxasset://.+"),
"GIFBackground.Asset must be a sprite sheet image ID or a local rbxasset:// image URI, not a GIF")
assert(typeof(ae.FrameSize)=="Vector2","GIFBackground.FrameSize must be a Vector2 in uploaded image pixels")
positiveInteger(ae.FrameSize.X,"FrameSize.X")
positiveInteger(ae.FrameSize.Y,"FrameSize.Y")
local af=positiveInteger(ae.Columns,"Columns")
local ag=positiveInteger(ae.Rows,"Rows")
local ah=positiveInteger(ae.FrameCount,"FrameCount")
assert(ah<=af*ag,"GIFBackground.FrameCount exceeds the sprite sheet grid")
assert(ae.Loop==nil or type(ae.Loop)=="boolean","GIFBackground.Loop must be boolean")
assert(ae.Enabled==nil or type(ae.Enabled)=="boolean","GIFBackground.Enabled must be boolean")
return{
Type="SpriteSheet",
Enabled=ae.Enabled~=false,
Asset=ae.Asset,
FrameSize=ae.FrameSize,
Columns=af,
Rows=ag,
FrameCount=ah,
FPS=math.clamp(number(ae.FPS,"FPS",24),1,60),
Transparency=math.clamp(number(ae.Transparency,"Transparency",0),0,1),
Loop=ae.Loop~=false,
}
end

function ad.new(ae,af,ag)
local ah=setmetatable({
Config=ad.Validate(ag),
Elapsed=0,
Frame=0,
Playing=true,
Finished=false,
Destroyed=false,
Connections={},
},ad)
ah.Image=ac.New("ImageLabel",{
Name="GIFBackground",
BackgroundTransparency=1,
Size=UDim2.fromScale(1,1),
ZIndex=1,
Active=false,
Selectable=false,
Image=ah.Config.Asset,
ImageRectSize=ah.Config.FrameSize,
ImageRectOffset=Vector2.zero,
ImageTransparency=ah.Config.Transparency,
ScaleType=Enum.ScaleType.Stretch,
Parent=ae,
},{
ac.New("UICorner",{CornerRadius=UDim.new(0,af)}),
})
local function connect(ai,aj)
table.insert(ah.Connections,ai:Connect(aj))
end
connect(ah.Image:GetPropertyChangedSignal"IsLoaded",function()ah:Refresh()end)

local ai=ah.Image
while ai do
if ai:IsA"GuiObject"then
connect(ai:GetPropertyChangedSignal"Visible",function()ah:Refresh()end)
elseif ai:IsA"LayerCollector"then
connect(ai:GetPropertyChangedSignal"Enabled",function()ah:Refresh()end)
end
ai=ai.Parent
end
connect(ae.Destroying,function()ah:Destroy()end)
connect(ah.Image.Destroying,function()ah:Destroy()end)
ah:Refresh()


task.spawn(function()
if ah.Destroyed then return end
local aj,ak=pcall(function()
ab:PreloadAsync{ah.Image}
end)
if ah.Destroyed then return end
ah:Refresh()
if not aj then warn("[WindUI.GIFBackground] Texture preload failed: "..tostring(ak))end
end)
return ah
end

function ad.IsVisible(ae)
local af=ae.Image
while af do
if af:IsA"GuiObject"and not af.Visible then return false end
if af:IsA"LayerCollector"and not af.Enabled then return false end
af=af.Parent
end
return ae.Image.Parent~=nil
end

function ad.Refresh(ae)
if ae.Destroyed then return end
local af=ae.Playing and not ae.Finished and ae.Config.Enabled
and ae.Config.Transparency<1 and ae.Image.IsLoaded and ae:IsVisible()
if af and not ae.Heartbeat then
ae.Heartbeat=aa.Heartbeat:Connect(function(ag)ae:Step(ag)end)
elseif not af and ae.Heartbeat then
ae.Heartbeat:Disconnect()
ae.Heartbeat=nil
end
end

function ad.Step(ae,af)
if ae.Destroyed then return end
local ag=ae.Config
ae.Elapsed=ae.Elapsed+af
local ah=math.floor(ae.Elapsed*ag.FPS)
if ag.Loop then

ae.Elapsed=ae.Elapsed%(ag.FrameCount/ag.FPS)
ah=ah%ag.FrameCount
elseif ah>=ag.FrameCount then
ah=ag.FrameCount-1
ae.Finished=true
ae:Refresh()
end
if ah~=ae.Frame then
ae.Frame=ah
ae.Image.ImageRectOffset=Vector2.new(
(ah%ag.Columns)*ag.FrameSize.X,
math.floor(ah/ag.Columns)*ag.FrameSize.Y
)
end
end

function ad.SetPlaying(ae,af)
ae.Playing=af
ae:Refresh()
end

function ad.SetTransparency(ae,af)
ae.Config.Transparency=math.clamp(number(af,"Transparency"),0,1)
ae.Image.ImageTransparency=ae.Config.Transparency
ae:Refresh()
end

function ad.Destroy(ae)
if ae.Destroyed then return end
ae.Destroyed=true
if ae.Heartbeat then
ae.Heartbeat:Disconnect()
ae.Heartbeat=nil
end
for af,ag in ipairs(ae.Connections)do ag:Disconnect()end
table.clear(ae.Connections)
ae.Image:Destroy()
end

return ad end function a.H()

