local function ContainsText(ax,ay)
if not ay or ay==""then
return false
end

if not ax or ax==""then
return false
end

local az=string.lower(ax)
local aA=string.lower(ay)

return string.find(az,aA,1,true)~=nil
end

local function Search(ax)
