local b={}

for d,f in next,aA.Elements do
if f.__type~="Section"then
local g=ContainsText(f.Title or"",ax)
local h=ContainsText(f.Desc or"",ax)

if g or h then
b[d]={
Title=f.Title,
Desc=f.Desc,
Original=f,
__type=f.__type,
Index=d,
}
end
end
end

if aB or next(b)~=nil then
ay[az]={
Tab=aA,
Title=aA.Title,
Icon=aA.Icon,
Elements=b,
}
end
end
return ay
end

