ay.Page=math.min(math.max(1,math.ceil(#al[aw]/20)),ay.Page+1);ay:Refresh()
end}
if aw=="History"then
ax:Button{Title="Vaciar historial",Icon="trash-2",Callback=function()al:ClearHistory();refresh()end}
end
for aB=1,20 do
ay.Rows[aB]=ax:Button{Title="",Desc="",Size="Small",Icon="chevron-right",Callback=function()
local aC=ay.Items[(ay.Page-1)*20+aB]
if aC then as:OpenItem(aC)end
end}
end
function ay.Refresh(aB)
if ak.Destroyed then return end
aB.Items=al[aw]
local aC=math.max(1,math.ceil(#aB.Items/20))
aB.Page=math.min(aB.Page,aC)
az:SetTitle(au.." · "..#aB.Items)
az:SetDesc(#aB.Items==0 and(aw=="Favorites"and"Guarda un script desde Explorar para encontrarlo aquí."or"Los scripts vistos y ejecutados aparecerán aquí.")
or"Página "..aB.Page.."/"..aC.." · Pulsa un script para abrirlo")
for b,d in ipairs(aB.Rows)do
local f=aB.Items[(aB.Page-1)*20+b]
d.ElementFrame.Visible=f~=nil
if f then
d:SetTitle(text(f.title))
d:SetDesc(text(f.game and f.game.name or"Universal")
..(aw=="History"and(" · "..text(f.Action or"Visto"))or""))
ao(d,as:Tags(f))
end
end
end
table.insert(ar,ay)
ay:Refresh()
return ay
end
an.Favorites=savedPanel("Favoritos","star","Favorites")
an.History=savedPanel("Historial","history","History")
an.Tabs.Favorites,an.Tabs.History=an.Favorites.Tab,an.History.Tab

local au=ak:Tab{Title="Editor",Icon="code"}
an.Tabs.Editor=au
au:Paragraph{Title="Editor local",Desc="Carga el script seleccionado o pega tu propio código. El borrador solo se ejecuta al pulsar Ejecutar."}
local av=au:Input{Title="Código Lua",Type="Textarea",Value="-- Escribe o pega tu código aquí.\n",Callback=function()end}
an.EditorInput=av
local aw=au:HStack{}
aw:Button{Title="Cargar seleccionado",Icon="download",Callback=function()
if not as.Code then notify("Sin selección","Selecciona primero un script en Explorar.");return end
if#as.Code>200000 then notify("Código demasiado grande","Usa Ver, Copiar o Ejecutar desde Explorar.");return end
av:Set(as.Code)
end}
aw:Button{Title="Copiar",Icon="copy",Callback=function()
local ax=setclipboard or toclipboard
if ax then
local ay=pcall(ax,av.Value or"")
notify(ay and"Borrador copiado"or"No se pudo copiar","")
else notify("Portapapeles no disponible","")end
end}
an.RunEditor=function()return as:ExecuteCode(av.Value,"Editor local")end
au:Button{Title="Ejecutar borrador",Icon="play",Callback=an.RunEditor}
local ax="WindUI/script-hub/editor-draft.lua"
an.SaveDraft=function()
if not writefile then notify("Guardado no disponible","");return false end
if#(av.Value or"")>200000 then notify("Borrador demasiado grande","Máximo 200.000 bytes para guardar y abrir.");return false end
local ay=pcall(function()
if makefolder and isfolder and not isfolder"WindUI/script-hub"then makefolder"WindUI/script-hub"end
writefile(ax,av.Value or"")
end)
notify(ay and"Borrador guardado"or"No se pudo guardar","Se guarda en este dispositivo.")
return ay
end
an.LoadDraft=function()
if not readfile then notify("Lectura no disponible","");return false end
local ay,az=pcall(readfile,ax)
if not ay or type(az)~="string"then notify("No hay borrador guardado","");return false end
if#az>200000 then notify("Borrador demasiado grande","Máximo 200.000 bytes en el editor.");return false end
av:Set(az);return true
end
local ay=au:HStack{}
ay:Button{Title="Guardar borrador",Icon="save",Callback=an.SaveDraft}
ay:Button{Title="Abrir guardado",Icon="folder-open",Callback=an.LoadDraft}

local az=ak:Tab{Title="Ajustes",Icon="settings"}
an.Tabs.Settings=az
az:Paragraph{Title="Tu espacio",Desc="El fondo de flores y los controles originales de WindUI se mantienen. Los cambios se recuerdan en este dispositivo."}
local aA,aB,aC=true,0,0
local function saveLater()
aC+=1
local b=aC
task.delay(0.4,function()if b==aC then al:Save();refresh()end end)
end
local function applyBackground()
aB+=1
local b=aB
task.delay(0.12,function()
if b~=aB or ak.Destroyed then return end
if not al.Settings.Background then ak:RemoveGIFBackground();return end
local d=table.clone(am)
d.Enabled,d.FPS,d.Transparency=true,al.Settings.FPS,al.Settings.Transparency
ak:SetGIFBackground(d)
ak.UIElements.GIFBackground.ScaleType=Enum.ScaleType.Crop
end)
end
local b=az:Toggle{Title="Fondo animado",Value=al.Settings.Background,Callback=function(b)
if aA then return end
al.Settings.Background=b;applyBackground();saveLater()
end}
local d=az:Slider{Title="Transparencia del fondo",Step=0.05,
Value={Min=0,Max=1,Default=al.Settings.Transparency},Callback=function(d)
if aA then return end
al.Settings.Transparency=d
ak:SetGIFBackgroundTransparency(d);saveLater()
end}
local f=az:Slider{Title="Velocidad del fondo (FPS)",Step=1,
Value={Min=1,Max=30,Default=math.min(30,al.Settings.FPS)},Callback=function(f)
if aA then return end
al.Settings.FPS=f;applyBackground();saveLater()
end}
an.SettingsUI={Enabled=b,Transparency=d,FPS=f}
az:Button{Title="Restaurar fondo original",Icon="rotate-ccw",Callback=function()
b:Set(true);d:Set(0.6);f:Set(10)
end}
az:Button{Title="Vaciar caché de búsqueda",Icon="refresh-cw",Callback=function()
as.Cache,as.CacheOrder={},{};notify("Caché vaciada","La próxima búsqueda consultará el catálogo.")
end}
local g=az:Paragraph{Title="Biblioteca local",Desc=al.Persistent and"Favoritos, historial y ajustes se guardan en este dispositivo."or"El executor permite guardar solo durante esta sesión."}
az:Button{Title="Guardar biblioteca ahora",Icon="save",Callback=function()
local h=al:Save()
g:SetDesc(h and"Biblioteca guardada correctamente."or"No se pudo guardar; los datos siguen disponibles en esta sesión.")
end}
aA=false
refresh()
as:RefreshCatalog()
ap:Select()
return an
end end end


